// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["GLOBAL_CONFIG.doppler_secrets_url", "GLOBAL_CONFIG.sage_gateway_url", "INV_PROC_CONFIG.sage_send_termname", "INV_PROC_CONFIG.sage_search_page_size"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

const LEGAL_SUFFIXES = /\b(incorporated|llc|l\.l\.c|inc|corp|corporation|co|company|ltd|limited|llp|lp|enterprises?|facilit(?:y|ies)|industries|international|the)\b/g;
function normVendor(raw) {
  if (!raw) return '';
  return String(raw).toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[.,\/#!$%\^*;:{}=\-_`~()'"]/g, ' ')
    .replace(LEGAL_SUFFIXES, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const arr = v => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');

function sageCreds() {
  const s = $('Doppler').first().json;
  const c = {
    sender: s.SAGE_SENDER_ID ?? s.SAGE_COMPANY_ID,
    senderPw: s.SAGE_SENDER_PASSWORD ?? s.SAGE_COMPANY_PASSWORD,
    company: s.SAGE_COMPANY_ID,
    user: s.SAGE_USER_ID ?? s.USER_ID,
    userPw: s.SAGE_USER_PASSWORD ?? s.USER_PASSWORD,
  };
  const missing = Object.entries(c).filter(([, v]) => !v).map(([k]) => k);
  if (missing.length) throw new Error(`Doppler is missing Sage secrets: ${missing.join(', ')}`);
  return c;
}

// Login auth on every request (no session step). locationId scopes the request to the entity.
function sageEnvelope(locationId, functionsXml) {
  const c = sageCreds();
  return `<?xml version="1.0" encoding="UTF-8"?>` +
    `<request><control><senderid>${esc(c.sender)}</senderid><password>${esc(c.senderPw)}</password>` +
    `<controlid>${Date.now()}</controlid><uniqueid>false</uniqueid><dtdversion>3.0</dtdversion><includewhitespace>false</includewhitespace></control>` +
    `<operation><authentication><login><userid>${esc(c.user)}</userid><companyid>${esc(c.company)}</companyid><password>${esc(c.userPw)}</password>` +
    (locationId ? `<locationid>${esc(locationId)}</locationid>` : '') +
    `</login></authentication><content>${functionsXml}</content></operation></request>`;
}

// Collect every <errormessage> in a parsed Sage response.
function sageErrors(o, acc = []) {
  if (!o || typeof o !== 'object') return acc;
  for (const [k, v] of Object.entries(o)) {
    if (k === 'errormessage') {
      for (const e of arr(v?.error)) {
        acc.push([e.errorno, e.description, e.description2, e.correction].filter(x => typeof x === 'string' && x.trim()).join(' — '));
      }
    } else if (v && typeof v === 'object') {
      sageErrors(v, acc);
    }
  }
  return acc;
}

// Sage returns HTTP 200 even on failure, so the status has to be read from the body.
function sageResults(j) {
  const resp = j?.response;
  if (!resp) {
    const e = j?.error;
    return { error: 'No parseable response from Sage' + (e ? `: ${typeof e === 'string' ? e : (e.message || JSON.stringify(e))}` : '') };
  }
  if (resp.control?.status !== 'success') return { error: 'Sage control block failed: ' + (sageErrors(resp).join(' | ') || 'no detail') };
  if (resp.operation?.authentication?.status !== 'success') return { error: 'Sage login failed: ' + (sageErrors(resp).join(' | ') || 'no detail') };
  return { list: arr(resp.operation?.result) };
}

// One request: vendor lookup + item GL lookup (only for lines without a GL).
const PAGE = $('Build Config').first().json.cfg.INV_PROC_CONFIG.sage_search_page_size;
const ctx = JSON.parse(JSON.stringify($('Start').first().json));
const p = ctx.payload;
if (!p) throw new Error('Sage Post called without a payload');

const fns = [];
if (p.vendor.sage_vendor_id) {
  fns.push(`<function controlid="vendorLookup"><query><object>VENDOR</object><select><field>VENDORID</field><field>NAME</field><field>STATUS</field></select>` +
    `<filter><equalto><field>VENDORID</field><value>${esc(p.vendor.sage_vendor_id)}</value></equalto></filter><pagesize>${PAGE}</pagesize></query></function>`);
} else {
  const words = normVendor(p.vendor.name).split(' ').filter(w => w.length > 1 && w !== 'and');
  const term = words.slice(0, 2).join(' ') || p.vendor.name;
  fns.push(`<function controlid="vendorLookup"><query><object>VENDOR</object><select><field>VENDORID</field><field>NAME</field><field>STATUS</field></select>` +
    `<filter><like><field>NAME</field><value>%${esc(term)}%</value></like></filter><options><caseinsensitive>true</caseinsensitive></options><pagesize>${PAGE}</pagesize></query></function>`);
}
const names = [...new Set(p.lines.filter(l => !l.gl_account).flatMap(l => l.item_names || []))];
if (names.length) {
  fns.push(`<function controlid="itemLookup"><query><object>ITEM</object><select><field>ITEMID</field><field>NAME</field><field>GLGROUP</field></select>` +
    `<filter><in><field>NAME</field>${names.map(n => `<value>${esc(n)}</value>`).join('')}</in></filter><pagesize>${PAGE}</pagesize></query></function>`);
}
ctx.sage_xml = sageEnvelope(p.location_id, fns.join(''));
return [{ json: ctx }];

