const ctx = JSON.parse(JSON.stringify($('Resolve Vendor & GL').first().json));
delete ctx.sage_xml;
delete ctx.sage_ready;
function findKey(o, k) {
  if (!o || typeof o !== 'object') return null;
  if (o[k] !== undefined) return o[k];
  for (const v of Object.values(o)) { const r = findKey(v, k); if (r !== null) return r; }
  return null;
}
const res = sageResults($input.first()?.json);
if (res.error) {
  ctx.status = 'POST_FAILED'; ctx.reason = res.error;
} else {
  const cr = res.list.find(x => x.controlid === 'createBill');
  if (cr?.status === 'success') {
    ctx.status = 'POSTED';
    ctx.sage_bill_id = String(findKey(cr.data, 'RECORDNO') ?? '') || null;
    ctx.posted_at = new Date().toISOString();
    ctx.reason = null;
  } else {
    ctx.status = 'POST_FAILED';
    ctx.reason = 'Sage rejected the bill: ' + (sageErrors(cr).join(' | ') || 'no error detail returned');
  }
}
return [{ json: ctx }];

