// Pick exactly one Sage vendor, fill item GLs, then build the APBILL create request.
const CONFIG = { SEND_TERMNAME: $('Build Config').first().json.cfg.INV_PROC_CONFIG.sage_send_termname === true };   // true only once invoice terms are mapped to Sage term names
const ctx = JSON.parse(JSON.stringify($('Build Lookup XML').first().json));
delete ctx.sage_xml;
ctx.sage_ready = false;
const p = ctx.payload;
const fail = (status, reason) => { ctx.status = status; ctx.reason = reason; return [{ json: ctx }]; };

const res = sageResults($input.first()?.json);
if (res.error) return fail('POST_FAILED', res.error);

// Vendor
const vr = res.list.find(x => x.controlid === 'vendorLookup');
if (!vr || vr.status !== 'success') return fail('POST_FAILED', 'Sage vendor lookup failed: ' + (sageErrors(vr).join(' | ') || 'no detail'));
const vendors = arr(vr.data?.VENDOR ?? vr.data?.vendor).filter(v => !v.STATUS || /^(active|t)$/i.test(String(v.STATUS)));
const target = normVendor(p.vendor.name);
let picks = vendors;
if (!p.vendor.sage_vendor_id) {
  picks = vendors.filter(v => normVendor(v.NAME) === target);
  if (!picks.length) picks = vendors.filter(v => { const n = normVendor(v.NAME); return n && target && (n.includes(target) || target.includes(n)); });
}
if (picks.length > 1 && p.vendor.location_code) {
  const local = picks.filter(v => String(v.VENDORID).toUpperCase().startsWith(p.vendor.location_code + '-'));
  if (local.length) picks = local;
}
if (!picks.length) return fail('VENDOR_NOT_FOUND', `No active Sage vendor matches "${p.vendor.name}"` + (p.vendor.sage_vendor_id ? ` (ID ${p.vendor.sage_vendor_id})` : ''));
if (picks.length > 1) return fail('VENDOR_AMBIGUOUS', `${picks.length} Sage vendors match "${p.vendor.name}": ` + picks.slice(0, 10).map(v => `${v.VENDORID} ${v.NAME}`).join('; '));
const vendorId = picks[0].VENDORID;
ctx.sage_vendor = { id: vendorId, name: picks[0].NAME };

// GL from item GL group (e.g. "5000 - Materials" -> 5000)
const glByName = {};
const ir = res.list.find(x => x.controlid === 'itemLookup');
for (const it of arr(ir?.data?.ITEM ?? ir?.data?.item)) {
  const g = String(it.GLGROUP ?? '').trim();
  const acct = (g.match(/^\s*([\w.]+)/) || [])[1];
  if (it.NAME && acct) glByName[String(it.NAME).trim().toUpperCase()] = { account: acct, group: g };
}
for (const line of p.lines) {
  if (line.gl_account) continue;
  const found = (line.item_names || []).map(n => glByName[String(n).trim().toUpperCase()]).filter(Boolean);
  if (!found.length) return fail('GL_NOT_FOUND', `No Sage item GL group for: ${(line.item_names || []).join(', ') || '(no PO items)'}`);
  line.gl_account = found[0].account;
  line.gl_name = found[0].group;
  const distinct = [...new Set(found.map(f => f.account))];
  if (distinct.length > 1) ctx.warnings.push(`PO items map to several GL accounts (${distinct.join(', ')}); posted to ${line.gl_account}`);
}

// APBILL
const mdy = iso => { const [y, m, d] = String(iso).split('-'); return `${m}/${d}/${y}`; };
const b = p.bill;
let x = `<APBILL><VENDORID>${esc(vendorId)}</VENDORID><WHENCREATED>${mdy(b.when_created)}</WHENCREATED>`;
if (b.when_due) x += `<WHENDUE>${mdy(b.when_due)}</WHENDUE>`;
else if (CONFIG.SEND_TERMNAME && b.term) x += `<TERMNAME>${esc(b.term)}</TERMNAME>`;
x += `<RECORDID>${esc(b.record_id)}</RECORDID>`;
if (b.doc_number) x += `<DOCNUMBER>${esc(b.doc_number)}</DOCNUMBER>`;
x += `<DESCRIPTION>${esc(String(b.description ?? '').slice(0, 1000))}</DESCRIPTION><APBILLITEMS>`;
for (const l of p.lines) {
  x += `<APBILLITEM><ACCOUNTNO>${esc(l.gl_account)}</ACCOUNTNO><TRX_AMOUNT>${Number(l.amount).toFixed(2)}</TRX_AMOUNT><ENTRYDESCRIPTION>${esc(l.memo)}</ENTRYDESCRIPTION>`;
  if (p.line_location_id) x += `<LOCATIONID>${esc(p.line_location_id)}</LOCATIONID>`;
  if (l.department) x += `<DEPARTMENTID>${esc(l.department)}</DEPARTMENTID>`;
  x += `</APBILLITEM>`;
}
x += `</APBILLITEMS></APBILL>`;

ctx.sage_xml = sageEnvelope(p.location_id, `<function controlid="createBill"><create>${x}</create></function>`);
ctx.sage_ready = true;
return [{ json: ctx }];
